import { describe, it, expect } from "vitest";
import { RedactorService } from "../src/services/redactor.js";

describe("Stress Test", () => {
  it("tests infinite loop bug on entity matching placeholder substring", async () => {
    const service = new RedactorService();
    // Use timeout to prevent test runner hanging forever
    const promise = service.redact("Mr. GIVEN_NAME was here");
    const timeout = new Promise((_, reject) => setTimeout(() => reject(new Error("TIMED_OUT")), 2000));
    await expect(Promise.race([promise, timeout])).resolves.toBeDefined();
  });
});

